```turtle
@prefix ea: <http://example.org/onto/assessment#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2007/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/assessment>
    a owl:Ontology ;
    rdfs:label "Educational Assessment Ontology"@en ;
    rdfs:comment "An ontology formalizing educational assessment, measurement, validity, reliability, scoring, and testing methods based directly on domain corpus texts."@en .

#################################################################
#    Root Domain Classes & Hierarchy
#################################################################

ea:Assessment
    a owl:Class ;
    rdfs:label "Assessment"@en ;
    skos:altLabel "Educational Assessment"@en , "Educational Evaluation"@en ;
    rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning."@en .

ea:Test
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Test"@en ;
    skos:altLabel "Examination"@en , "Exam"@en , "Evaluation"@en ;
    rdfs:comment "An assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification across educational topics."@en .

ea:AssessmentItem
    a owl:Class ;
    rdfs:label "Assessment Item"@en ;
    skos:altLabel "Question"@en , "Test Item"@en ;
    rdfs:comment "A component item or prompt presented in an assessment."@en .

ea:ScoringTool
    a owl:Class ;
    rdfs:label "Scoring Tool"@en ;
    rdfs:comment "An instrument, guideline, or guide used to evaluate, grade, or score assessment performances."@en .

ea:AssessmentEvidence
    a owl:Class ;
    rdfs:label "Assessment Evidence"@en ;
    rdfs:comment "Empirical information, student work, or performance data gathered during assessment."@en .

ea:LearningOutcome
    a owl:Class ;
    rdfs:label "Learning Outcome"@en ;
    skos:altLabel "Intended Learning Outcome"@en , "Learning Standard"@en ;
    rdfs:comment "Statements specifying what students should know or be able to do at a particular stage of instruction."@en .

ea:CutScore
    a owl:Class ;
    rdfs:label "Cut Score"@en ;
    skos:altLabel "Passing Score"@en , "Cut-off Score"@en ;
    rdfs:comment "A predetermined threshold score used to establish whether a candidate passes or achieves proficiency."@en .

ea:Feedback
    a owl:Class ;
    rdfs:label "Feedback"@en ;
    rdfs:comment "Qualitative or quantitative information returned to learners or instructors regarding assessment performance."@en .

ea:PsychometricQuality
    a owl:Class ;
    rdfs:label "Psychometric Quality"@en ;
    rdfs:comment "Quality attributes of assessment measurement, centrally including reliability and validity."@en .

ea:MeasurementError
    a owl:Class ;
    rdfs:label "Measurement Error"@en ;
    rdfs:comment "The discrepancy between scores obtained on tests and the corresponding true scores, composed of random and systematic error."@en .

ea:NormGroup
    a owl:Class ;
    rdfs:label "Norm Group"@en ;
    skos:altLabel "Norming Group"@en , "Reference Population"@en ;
    rdfs:comment "A statistically selected comparison group of previous test takers whose performance sets the benchmark for norm-referencing."@en .

#################################################################
#    Axis 1: Purpose Category Reification & Bridge Definitions
#################################################################

ea:AssessmentPurpose
    a owl:Class ;
    rdfs:label "Assessment Purpose"@en ;
    rdfs:comment "Reified axis class categorizing the functional educational purpose and timing of an assessment." ;
    owl:disjointUnionOf (
        ea:PlacementPurpose
        ea:DiagnosticPurpose
        ea:FormativePurpose
        ea:SummativePurpose
        ea:InterimPurpose
        ea:ScreeningPurpose
    ) .

ea:PlacementPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Placement Purpose"@en ;
    skos:altLabel "Initial Purpose"@en , "Pre-assessment Purpose"@en .

ea:DiagnosticPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Diagnostic Purpose"@en .

ea:FormativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Formative Purpose"@en ;
    skos:altLabel "Educative Purpose"@en , "Assessment For Learning Purpose"@en .

ea:SummativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Summative Purpose"@en ;
    skos:altLabel "Assessment Of Learning Purpose"@en .

ea:InterimPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Interim Purpose"@en ;
    skos:altLabel "Benchmark Purpose"@en .

ea:ScreeningPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Screening Purpose"@en .

ea:hasAssessmentPurpose
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:AssessmentPurpose ;
    rdfs:label "has assessment purpose"@en .

ea:isAssessmentPurposeOf
    a owl:ObjectProperty ;
    owl:inverseOf ea:hasAssessmentPurpose ;
    rdfs:domain ea:AssessmentPurpose ;
    rdfs:range ea:Assessment ;
    rdfs:label "is assessment purpose of"@en .

ea:PlacementAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en , "Pre-assessment"@en , "Threshold Knowledge Test"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentPurpose ;
                owl:someValuesFrom ea:PlacementPurpose
            ]
        )
    ] .

ea:FormativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Formative Assessment"@en ;
    skos:altLabel "Educative Assessment"@en , "Classroom Assessment"@en , "Assessment For Learning"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentPurpose ;
                owl:someValuesFrom ea:FormativePurpose
            ]
        )
    ] .

ea:SummativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Summative Assessment"@en ;
    skos:altLabel "Assessment Of Learning"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentPurpose ;
                owl:someValuesFrom ea:SummativePurpose
            ]
        )
    ] .

ea:DiagnosticAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Diagnostic Assessment"@en ;
    skos:altLabel "Diagnostic Testing"@en ;
    rdfs:comment "Corpus tension: One passage presents diagnostic assessment as an independent coordinate category alongside placement, formative, and summative assessments; another states that 'a common form of formative assessment is diagnostic assessment'; yet another states diagnostic assessment occurs 'at the end' to focus on difficulties throughout learning. Both conceptualizations are captured."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentPurpose ;
                owl:someValuesFrom ea:DiagnosticPurpose
            ]
        )
    ] .

ea:InterimAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Interim Assessment"@en ;
    skos:altLabel "Benchmark Assessment"@en ;
    rdfs:comment "Corpus tension: Interim assessments are administered periodically to monitor progress toward end-of-course tests; some educators classify them as formative (since used diagnostically) while others consider them summative."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentPurpose ;
                owl:someValuesFrom ea:InterimPurpose
            ]
        )
    ] .

ea:ScreeningAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Screening Assessment"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentPurpose ;
                owl:someValuesFrom ea:ScreeningPurpose
            ]
        )
    ] .

#################################################################
#    Axis 2: Score Referencing Framework Reification
#################################################################

ea:ReferencingFramework
    a owl:Class ;
    rdfs:label "Referencing Framework"@en ;
    rdfs:comment "Reified axis class for the basis of test score comparison and interpretation." ;
    owl:disjointUnionOf (
        ea:CriterionReferencing
        ea:NormReferencing
        ea:IpsativeReferencing
    ) .

ea:CriterionReferencing
    a owl:Class ;
    rdfs:subClassOf ea:ReferencingFramework ;
    rdfs:label "Criterion Referencing"@en ;
    skos:altLabel "Standards-based Referencing"@en .

ea:NormReferencing
    a owl:Class ;
    rdfs:subClassOf ea:ReferencingFramework ;
    rdfs:label "Norm Referencing"@en ;
    skos:altLabel "Curved Referencing"@en .

ea:IpsativeReferencing
    a owl:Class ;
    rdfs:subClassOf ea:ReferencingFramework ;
    rdfs:label "Ipsative Referencing"@en ;
    skos:altLabel "Forced-choice Referencing"@en .

ea:hasReferencingFramework
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:ReferencingFramework ;
    rdfs:label "has referencing framework"@en .

ea:isReferencingFrameworkOf
    a owl:ObjectProperty ;
    owl:inverseOf ea:hasReferencingFramework ;
    rdfs:domain ea:ReferencingFramework ;
    rdfs:range ea:Assessment ;
    rdfs:label "is referencing framework of"@en .

ea:CriterionReferencedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Criterion-Referenced Assessment"@en ;
    skos:altLabel "Criterion-Referenced Test"@en , "Standards-Based Assessment"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasReferencingFramework ;
                owl:someValuesFrom ea:CriterionReferencing
            ]
        )
    ] .

ea:NormReferencedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Norm-Referenced Assessment"@en ;
    skos:altLabel "Norm-Referenced Test"@en , "Normative Assessment"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasReferencingFramework ;
                owl:someValuesFrom ea:NormReferencing
            ]
        )
    ] .

ea:IpsativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Ipsative Assessment"@en ;
    skos:altLabel "Self-comparison Assessment"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasReferencingFramework ;
                owl:someValuesFrom ea:IpsativeReferencing
            ]
        )
    ] .

#################################################################
#    Axis 3: Questioning / Scoring Objectivity Reification
#################################################################

ea:ScoringObjectivity
    a owl:Class ;
    rdfs:label "Scoring Objectivity"@en ;
    rdfs:comment "Reified axis class categorizing questioning and scoring objectivity." ;
    owl:disjointUnionOf (
        ea:ObjectiveScoring
        ea:SubjectiveScoring
    ) .

ea:ObjectiveScoring
    a owl:Class ;
    rdfs:subClassOf ea:ScoringObjectivity ;
    rdfs:label "Objective Scoring"@en .

ea:SubjectiveScoring
    a owl:Class ;
    rdfs:subClassOf ea:ScoringObjectivity ;
    rdfs:label "Subjective Scoring"@en .

ea:hasScoringObjectivity
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:ScoringObjectivity ;
    rdfs:label "has scoring objectivity"@en .

ea:isScoringObjectivityOf
    a owl:ObjectProperty ;
    owl:inverseOf ea:hasScoringObjectivity ;
    rdfs:domain ea:ScoringObjectivity ;
    rdfs:range ea:Assessment ;
    rdfs:label "is scoring objectivity of"@en .

ea:ObjectiveAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Objective Assessment"@en ;
    rdfs:comment "A form of questioning that has a single correct answer."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasScoringObjectivity ;
                owl:someValuesFrom ea:ObjectiveScoring
            ]
        )
    ] .

ea:SubjectiveAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Subjective Assessment"@en ;
    rdfs:comment "A form of questioning that may have more than one correct answer or more than one way of expressing the correct answer."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasScoringObjectivity ;
                owl:someValuesFrom ea:SubjectiveScoring
            ]
        )
    ] .

#################################################################
#    Axis 4: Formality Reification
#################################################################

ea:AssessmentFormality
    a owl:Class ;
    rdfs:label "Assessment Formality"@en ;
    owl:disjointUnionOf (
        ea:FormalFormality
        ea:InformalFormality
    ) .

ea:FormalFormality
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentFormality ;
    rdfs:label "Formal Formality"@en .

ea:InformalFormality
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentFormality ;
    rdfs:label "Informal Formality"@en .

ea:hasAssessmentFormality
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:AssessmentFormality ;
    rdfs:label "has assessment formality"@en .

ea:isAssessmentFormalityOf
    a owl:ObjectProperty ;
    owl:inverseOf ea:hasAssessmentFormality ;
    rdfs:domain ea:AssessmentFormality ;
    rdfs:range ea:Assessment ;
    rdfs:label "is assessment formality of"@en .

ea:FormalAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Formal Assessment"@en ;
    rdfs:comment "An assessment given a numerical score or grade based on student performance, usually implying a written document."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentFormality ;
                owl:someValuesFrom ea:FormalFormality
            ]
        )
    ] .

ea:InformalAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Informal Assessment"@en ;
    rdfs:comment "An assessment that does not contribute to a student's final grade, occurring more casually."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentFormality ;
                owl:someValuesFrom ea:InformalFormality
            ]
        )
    ] .

#################################################################
#    Axis 5: Administrative Origin Reification (Internal vs External)
#################################################################

ea:AdministrativeOrigin
    a owl:Class ;
    rdfs:label "Administrative Origin"@en ;
    owl:disjointUnionOf (
        ea:InternalOrigin
        ea:ExternalOrigin
    ) .

ea:InternalOrigin
    a owl:Class ;
    rdfs:subClassOf ea:AdministrativeOrigin ;
    rdfs:label "Internal Origin"@en .

ea:ExternalOrigin
    a owl:Class ;
    rdfs:subClassOf ea:AdministrativeOrigin ;
    rdfs:label "External Origin"@en .

ea:hasAdministrativeOrigin
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:AdministrativeOrigin ;
    rdfs:label "has administrative origin"@en .

ea:isAdministrativeOriginOf
    a owl:ObjectProperty ;
    owl:inverseOf ea:hasAdministrativeOrigin ;
    rdfs:domain ea:AdministrativeOrigin ;
    rdfs:range ea:Assessment ;
    rdfs:label "is administrative origin of"@en .

ea:InternalAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Internal Assessment"@en ;
    rdfs:comment "Assessment set and marked by the school (i.e., teachers)."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAdministrativeOrigin ;
                owl:someValuesFrom ea:InternalOrigin
            ]
        )
    ] .

ea:ExternalAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "External Assessment"@en ;
    rdfs:comment "Assessment set by a governing body and marked by external or unbiased personnel."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAdministrativeOrigin ;
                owl:someValuesFrom ea:ExternalOrigin
            ]
        )
    ] .

#################################################################
#    Axis 6: Standardization Reification
#################################################################

ea:StandardizationCondition
    a owl:Class ;
    rdfs:label "Standardization Condition"@en ;
    owl:disjointUnionOf (
        ea:StandardizedCondition
        ea:NonStandardizedCondition
    ) .

ea:StandardizedCondition
    a owl:Class ;
    rdfs:subClassOf ea:StandardizationCondition ;
    rdfs:label "Standardized Condition"@en .

ea:NonStandardizedCondition
    a owl:Class ;
    rdfs:subClassOf ea:StandardizationCondition ;
    rdfs:label "Non-standardized Condition"@en .

ea:hasStandardizationCondition
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:StandardizationCondition ;
    rdfs:label "has standardization condition"@en .

ea:isStandardizationConditionOf
    a owl:ObjectProperty ;
    owl:inverseOf ea:hasStandardizationCondition ;
    rdfs:domain ea:StandardizationCondition ;
    rdfs:range ea:Assessment ;
    rdfs:label "is standardization condition of"@en .

ea:StandardizedTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Standardized Test"@en ;
    rdfs:comment "A test administered and scored in a predetermined, standard, and uniform manner for all test takers."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Test
            [
                a owl:Restriction ;
                owl:onProperty ea:hasStandardizationCondition ;
                owl:someValuesFrom ea:StandardizedCondition
            ]
        )
    ] .

ea:NonStandardizedTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Non-standardized Test"@en ;
    rdfs:comment "A test where significantly different tests are given to different test takers, or assigned under different conditions, or evaluated differently."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Test
            [
                a owl:Restriction ;
                owl:onProperty ea:hasStandardizationCondition ;
                owl:someValuesFrom ea:NonStandardizedCondition
            ]
        )
    ] .

#################################################################
#    Axis 7: Stakes Level Reification
#################################################################

ea:StakesLevel
    a owl:Class ;
    rdfs:label "Stakes Level"@en ;
    owl:disjointUnionOf (
        ea:HighStakesLevel
        ea:LowStakesLevel
    ) .

ea:HighStakesLevel
    a owl:Class ;
    rdfs:subClassOf ea:StakesLevel ;
    rdfs:label "High Stakes Level"@en .

ea:LowStakesLevel
    a owl:Class ;
    rdfs:subClassOf ea:StakesLevel ;
    rdfs:label "Low Stakes Level"@en .

ea:hasStakesLevel
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:StakesLevel ;
    rdfs:label "has stakes level"@en .

ea:isStakesLevelOf
    a owl:ObjectProperty ;
    owl:inverseOf ea:hasStakesLevel ;
    rdfs:domain ea:StakesLevel ;
    rdfs:range ea:Assessment ;
    rdfs:label "is stakes level of"@en .

ea:HighStakesTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "High-Stakes Test"@en ;
    rdfs:comment "A test with important consequences for the individual test taker or institution, such as licensure, graduation, funding, or sanctions."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Test
            [
                a owl:Restriction ;
                owl:onProperty ea:hasStakesLevel ;
                owl:someValuesFrom ea:HighStakesLevel
            ]
        )
    ] .

ea:LowStakesTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Low-Stakes Test"@en ;
    rdfs:comment "A test carrying low or no point value and no significant or public consequences."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Test
            [
                a owl:Restriction ;
                owl:onProperty ea:hasStakesLevel ;
                owl:someValuesFrom ea:LowStakesLevel
            ]
        )
    ] .

#################################################################
#    Assessment Delivery & Medium Modalities
#################################################################

ea:WrittenTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Written Test"@en ;
    rdfs:comment "A test administered on paper or on a computer where test takers respond by writing or typing."@en .

ea:OralTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Oral Test"@en ;
    rdfs:comment "A test administered verbally."@en .

ea:PracticalTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Practical Test"@en ;
    skos:altLabel "Performance Test"@en ;
    rdfs:comment "A test requiring an examinee to demonstrate or perform a set of physical or practical skills."@en .

[ a owl:AllDisjointClasses ;
  owl:members ( ea:WrittenTest ea:OralTest ea:PracticalTest )
] .

ea:ComputerBasedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Computer-Based Assessment"@en ;
    skos:altLabel "Online Assessment"@en , "eExam"@en , "On-screen Test"@en ;
    rdfs:comment "An assessment administered and delivered via computer or online network."@en .

ea:PaperBasedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Paper-Based Assessment"@en ;
    rdfs:comment "An assessment presented on paper and completed using pencils or pens."@en .

#################################################################
#    Performance-Based and Authentic Assessments
#################################################################

ea:PerformanceBasedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Performance-Based Assessment"@en ;
    skos:altLabel "Performance Assessment"@en ;
    rdfs:comment "An assessment requiring students to solve real-world problems or perform a well-defined task resulting in a product or performance."@en .

ea:AuthenticAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Authentic Assessment"@en ;
    rdfs:comment "The measurement of accomplishments within a realistic, practical context relevant outside school."@en .

ea:PortfolioBasedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Portfolio-Based Assessment"@en ;
    rdfs:comment "An assessment based on a compilation of academic work assembled over time."@en .

ea:ContinuousAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Continuous Assessment"@en ;
    rdfs:comment "An assessment process that evaluates student progress throughout a course rather than through a single terminal exam."@en .

ea:ComplexAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Complex Assessment"@en ;
    rdfs:comment "An assessment characterized by format implicitness that requires a rubric and an expert examiner, such as a thesis or funding proposal."@en .

ea:ForwardLookingAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Forward-Looking Assessment"@en ;
    rdfs:comment "An assessment asking test takers to consider themselves in hypothetical future situations."@en .

#################################################################
#    Specific Institutional Assessment Types
#################################################################

ea:Quiz
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Quiz"@en ;
    rdfs:comment "A brief assessment covering a small amount of material from recent instruction."@en .

ea:MidtermExam
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Midterm Exam"@en ;
    rdfs:comment "An examination administered near the middle of an academic term, serving formative or summative purposes."@en .

ea:FinalExam
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Final Exam"@en ;
    skos:altLabel "Final Examination"@en , "Finals"@en ;
    rdfs:comment "A comprehensive summative examination administered at the conclusion of a course or degree program."@en .

ea:CompetitiveExam
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Competitive Exam"@en ;
    skos:altLabel "Competitive Examination"@en ;
    rdfs:comment "A norm-referenced, high-stakes test where candidates are ranked to select the top rankers for a fixed number of positions."@en .

ea:CollegeAdmissionsTest
    a owl:Class ;
    rdfs:subClassOf ea:StandardizedTest ;
    rdfs:label "College Admissions Test"@en ;
    rdfs:comment "A standardized test used in decisions about university entrance, such as the SAT or ACT."@en .

ea:InternationalComparisonTest
    a owl:Class ;
    rdfs:subClassOf ea:StandardizedTest ;
    rdfs:label "International Comparison Test"@en ;
    rdfs:comment "A standardized test administered across countries to monitor and compare achievement trends, such as PISA, TIMSS, or PIRLS."@en .

ea:PsychologicalTest
    a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:label "Psychological Test"@en ;
    rdfs:comment "A test used to measure cognitive abilities, emotional characteristics, or intelligence, such as an IQ test."@en .

#################################################################
#    Assessment Items & Item Components
#################################################################

ea:ObjectiveItem
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentItem ;
    rdfs:label "Objective Item"@en ;
    rdfs:comment "A closed-ended assessment item format with predetermined correct answers."@en .

ea:SubjectiveItem
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentItem ;
    rdfs:label "Subjective Item"@en ;
    skos:altLabel "Open-Ended Item"@en ;
    rdfs:comment "An item requiring constructed prose or extended responses that require human or rubric-based scoring."@en .

ea:MultipleChoiceItem
    a owl:Class ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "Multiple-Choice Item"@en ;
    skos:altLabel "MCQ"@en , "One-Best-Answer Question"@en ;
    rdfs:comment "An item consisting of a stem and several alternative answers, exactly one of which is keyed as correct."@en .

ea:MultipleResponseItem
    a owl:Class ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "Multiple-Response Item"@en ;
    rdfs:comment "An item where more than one alternative answer may be keyed as correct."@en .

ea:TrueFalseItem
    a owl:Class ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "True-False Item"@en ;
    rdfs:comment "An objective item requiring the test taker to verify statements as true or false."@en .

ea:MatchingItem
    a owl:Class ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "Matching Item"@en ;
    rdfs:comment "An objective item requiring test takers to pair related options."@en .

ea:FillInTheBlankItem
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentItem ;
    rdfs:label "Fill-in-the-Blank Item"@en ;
    rdfs:comment "An item providing identifying characteristics and requiring recall of the correct term, with or without a word bank."@en .

ea:EssayItem
    a owl:Class ;
    rdfs:subClassOf ea:SubjectiveItem ;
    rdfs:label "Essay Item"@en ;
    skos:altLabel "Free Response Question"@en , "FRQ"@en ;
    rdfs:comment "A subjective open-ended item requiring the candidate to write an extended prose response."@en .

ea:ShortAnswerItem
    a owl:Class ;
    rdfs:subClassOf ea:SubjectiveItem ;
    rdfs:label "Short-Answer Item"@en ;
    rdfs:comment "A brief constructed-response item."@en .

[ a owl:AllDisjointClasses ;
  owl:members ( ea:MultipleChoiceItem ea:MultipleResponseItem ea:TrueFalseItem ea:MatchingItem ea:EssayItem ea:ShortAnswerItem )
] .

ea:Stem
    a owl:Class ;
    rdfs:label "Stem"@en ;
    rdfs:comment "The opening problem, question, or incomplete statement of an item."@en .

ea:ItemOption
    a owl:Class ;
    rdfs:label "Item Option"@en ;
    skos:altLabel "Alternative Answer"@en ;
    rdfs:comment "A possible answer option presented in an objective item." ;
    owl:disjointUnionOf (
        ea:CorrectKey
        ea:Distractor
    ) .

ea:CorrectKey
    a owl:Class ;
    rdfs:subClassOf ea:ItemOption ;
    rdfs:label "Correct Key"@en ;
    skos:altLabel "Key"@en .

ea:Distractor
    a owl:Class ;
    rdfs:subClassOf ea:ItemOption ;
    rdfs:label "Distractor"@en ;
    rdfs:comment "An incorrect but plausible alternative answer designed by the test maker."@en .

#################################################################
#    Scoring, Grading, and Rubrics
#################################################################

ea:Rubric
    a owl:Class ;
    rdfs:subClassOf ea:ScoringTool ;
    rdfs:label "Rubric"@en ;
    skos:altLabel "Scoring Guide"@en ;
    rdfs:comment "A scoring guide in table format used to evaluate constructed responses, containing evaluative criteria and quality definitions across achievement levels."@en .

ea:HolisticRubric
    a owl:Class ;
    rdfs:subClassOf ea:Rubric ;
    rdfs:label "Holistic Rubric"@en ;
    rdfs:comment "A rubric providing an overall rating for a piece of work, considering all aspects together."@en .

ea:AnalyticRubric
    a owl:Class ;
    rdfs:subClassOf ea:Rubric ;
    rdfs:label "Analytic Rubric"@en ;
    rdfs:comment "A rubric that evaluates various dimensions or components separately."@en .

ea:DevelopmentalRubric
    a owl:Class ;
    rdfs:subClassOf ea:AnalyticRubric ;
    rdfs:label "Developmental Rubric"@en ;
    rdfs:comment "A subset of analytic rubrics that facilitates assessment and learning across dimensions of developmental successions."@en .

ea:HolisticScoring
    a owl:Class ;
    rdfs:subClassOf ea:ScoringTool ;
    rdfs:label "Holistic Scoring"@en ;
    skos:altLabel "Holistic Grading"@en , "Nonreductionist Grading"@en ;
    rdfs:comment "Scoring that appraises student work as an integrated entity rather than assigning separate values to components."@en .

ea:AnalyticScoring
    a owl:Class ;
    rdfs:subClassOf ea:ScoringTool ;
    rdfs:label "Analytic Scoring"@en ;
    skos:altLabel "Analytic Grading"@en ;
    rdfs:comment "Scoring that involves criterion-by-criterion independent judgments across traits."@en .

ea:TraitInformedScoring
    a owl:Class ;
    rdfs:subClassOf ea:HolisticScoring ;
    rdfs:label "Trait-Informed Scoring"@en ;
    rdfs:comment "A form of holistic scoring where raters score to a guide taking into account multiple traits before deciding on a single score."@en .

#################################################################
#    Psychometric Qualities: Reliability & Validity
#################################################################

ea:Reliability
    a owl:Class ;
    rdfs:subClassOf ea:PsychometricQuality ;
    rdfs:label "Reliability"@en ;
    rdfs:comment "The consistency, reproducibility, and freedom from measurement error of assessment scores."@en .

ea:TestRetestReliability
    a owl:Class ;
    rdfs:subClassOf ea:Reliability ;
    rdfs:label "Test-Retest Reliability"@en ;
    skos:altLabel "Repeatability"@en , "Temporal Stability"@en ;
    rdfs:comment "Consistency of test scores from one test administration to the next under the same conditions."@en .

ea:AlternateFormReliability
    a owl:Class ;
    rdfs:subClassOf ea:Reliability ;
    rdfs:label "Alternate-Form Reliability"@en ;
    skos:altLabel "Parallel-Forms Reliability"@en , "Form Equivalence"@en , "Inter-Method Reliability"@en ;
    rdfs:comment "Equivalence of examinee performance on different forms of a test based on the same content."@en .

ea:InternalConsistencyReliability
    a owl:Class ;
    rdfs:subClassOf ea:Reliability ;
    rdfs:label "Internal Consistency Reliability"@en ;
    rdfs:comment "Consistency of results across items within a test, measured commonly by Cronbach's alpha or split-half methods."@en .

ea:InterRaterReliability
    a owl:Class ;
    rdfs:subClassOf ea:Reliability ;
    rdfs:label "Inter-Rater Reliability"@en ;
    skos:altLabel "Inter-Rater Agreement"@en , "Rater Reliability"@en ;
    rdfs:comment "The degree of agreement between two or more independent raters in their appraisals."@en .

ea:SplitHalfReliability
    a owl:Class ;
    rdfs:subClassOf ea:InternalConsistencyReliability ;
    rdfs:label "Split-Half Reliability"@en ;
    rdfs:comment "Reliability estimated by splitting a test into two halves (e.g. odd-even) and correlating scores."@en .

ea:Validity
    a owl:Class ;
    rdfs:subClassOf ea:PsychometricQuality ;
    rdfs:label "Validity"@en ;
    skos:altLabel "Test Validity"@en ;
    rdfs:comment "The degree to which a measurement tool measures what it claims or is intended to measure."@en .

ea:ConstructValidity
    a owl:Class ;
    rdfs:subClassOf ea:Validity ;
    rdfs:label "Construct Validity"@en ;
    rdfs:comment "The overarching extent to which operationalizations of a construct measure the construct as defined by theory, subsuming all other validity evidence."@en .

ea:ContentValidity
    a owl:Class ;
    rdfs:subClassOf ea:Validity ;
    rdfs:label "Content Validity"@en ;
    skos:altLabel "Logical Validity"@en , "Subject-Matter Validity"@en ;
    rdfs:comment "The systematic examination of test content to determine whether it covers a representative sample of the domain."@en .

ea:CriterionValidity
    a owl:Class ;
    rdfs:subClassOf ea:Validity ;
    rdfs:label "Criterion Validity"@en ;
    skos:altLabel "Criterion-Related Validity"@en ;
    rdfs:comment "The extent to which test scores correlate with an outside criterion variable or outcome."@en .

ea:ConcurrentValidity
    a owl:Class ;
    rdfs:subClassOf ea:CriterionValidity ;
    rdfs:label "Concurrent Validity"@en ;
    rdfs:comment "Criterion validity evidence where test data and criterion measures are gathered at approximately the same time."@en .

ea:PredictiveValidity
    a owl:Class ;
    rdfs:subClassOf ea:CriterionValidity ;
    rdfs:label "Predictive Validity"@en ;
    rdfs:comment "Criterion validity evidence where test data predict criterion data collected at a future point in time."@en .

ea:ConvergentValidity
    a owl:Class ;
    rdfs:subClassOf ea:ConstructValidity ;
    rdfs:label "Convergent Validity"@en ;
    rdfs:comment "The degree to which two measures of constructs that theoretically should be related are in fact related."@en .

ea:DiscriminantValidity
    a owl:Class ;
    rdfs:subClassOf ea:ConstructValidity ;
    rdfs:label "Discriminant Validity"@en ;
    skos:altLabel "Divergent Validity"@en ;
    rdfs:comment "The degree to which concepts or measurements that are supposed to be unrelated are in fact unrelated."@en .

ea:FaceValidity
    a owl:Class ;
    rdfs:subClassOf ea:Validity ;
    rdfs:label "Face Validity"@en ;
    rdfs:comment "A subjective estimate of whether a test appears or looks superficially to measure a certain criterion."@en .

ea:ConsequentialValidity
    a owl:Class ;
    rdfs:subClassOf ea:Validity ;
    rdfs:label "Consequential Validity"@en ;
    rdfs:comment "Validity evidence concerning the social and educational consequences of test score interpretation and use."@en .

#################################################################
#    Feedback and Value-Added Evaluation Concepts
#################################################################

ea:CorrectiveFeedback
    a owl:Class ;
    rdfs:subClassOf ea:Feedback ;
    rdfs:label "Corrective Feedback"@en ;
    rdfs:comment "Feedback on student understanding or performance designed to be nonevaluative, supportive, timely, and specific."@en .

ea:ValueAddedMeasure
    a owl:Class ;
    rdfs:label "Value-Added Measure"@en ;
    skos:altLabel "Growth Measure"@en ;
    rdfs:comment "A statistical method isolating an individual teacher's contribution to student learning progress based on test score trajectories."@en .

ea:Portfolio
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentEvidence ;
    rdfs:label "Student Portfolio"@en ;
    skos:altLabel "ePortfolio"@en , "Digital Portfolio"@en ;
    rdfs:comment "A compilation of academic work and evidence assembled over time to evaluate quality, learning progress, and achievement."@en .

