#################################################################
#    Cardinality Restrictions & Structural Axioms
#################################################################

ea:MultipleChoiceItem
    rdfs:subClassOf [
        a owl:Restriction ;
        owl:onProperty ea:hasStem ;
        owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ;
        owl:onClass ea:Stem
    ] , [
        a owl:Restriction ;
        owl:onProperty ea:hasItemOption ;
        owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ;
        owl:onClass ea:CorrectKey
    ] , [
        a owl:Restriction ;
        owl:onProperty ea:hasItemOption ;
        owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
        owl:onClass ea:Distractor
    ] .

ea:MultipleResponseItem
    rdfs:subClassOf [
        a owl:Restriction ;
        owl:onProperty ea:hasItemOption ;
        owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ;
        owl:onClass ea:CorrectKey
    ] .

ea:ComplexAssessment
    rdfs:subClassOf [
        a owl:Restriction ;
        owl:onProperty ea:hasRubric ;
        owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
        owl:onClass ea:Rubric
    ] .
